## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "beeftv.plugin/v2",
  "id": "rightapi-image",
  "name": "RightAPI Draw Image",
  "version": "2.0.0",
  "author": "BeefTV Contributors",
  "description": "RightAPI Draw Image 独立请求协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "rightapi-image",
        "label": "RightAPI Draw Image",
        "capabilities": [
          "image"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://www.right.codes",
        "requiresPublicMediaUrls": false,
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "图片模型 ID。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "图片提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "provider image/reference fields",
            "description": "参考图或编辑源图，role 由业务层确定。"
          },
          {
            "name": "imageCount",
            "type": "integer",
            "required": false,
            "mapping": "n/sample_count",
            "description": "输出数量。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "size/aspect_ratio",
            "description": "比例或尺寸，语义按协议说明。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "resolution/imageSize",
            "description": "分辨率档位。"
          },
          {
            "name": "quality",
            "type": "string",
            "required": false,
            "mapping": "quality",
            "description": "质量档位。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/draw/v1/images/generations",
          "contentType": "application/json",
          "body": {
            "$merge": [
              {
                "model": {
                  "$ref": "request.model"
                },
                "prompt": {
                  "$ref": "request.prompt"
                },
                "async": true,
                "n": {
                  "$if": {
                    "condition": {
                      "$gt": [
                        {
                          "$toInt": {
                            "$ref": "request.imageCount"
                          }
                        },
                        0
                      ]
                    },
                    "then": {
                      "$toInt": {
                        "$ref": "request.imageCount"
                      }
                    },
                    "else": 1
                  }
                },
                "size": {
                  "$omitEmpty": {
                    "$if": {
                      "condition": {
                        "$eq": [
                          {
                            "$ref": "request.aspectRatio"
                          },
                          "auto"
                        ]
                      },
                      "then": null,
                      "else": {
                        "$ref": "request.aspectRatio"
                      }
                    }
                  }
                },
                "imageSize": {
                  "$omitEmpty": {
                    "$switch": {
                      "cases": [
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "low"
                            ]
                          },
                          "then": "1K"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "1k"
                            ]
                          },
                          "then": "1K"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "medium"
                            ]
                          },
                          "then": "2K"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "2k"
                            ]
                          },
                          "then": "2K"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "high"
                            ]
                          },
                          "then": "4K"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.quality"
                                  }
                                }
                              },
                              "4k"
                            ]
                          },
                          "then": "4K"
                        }
                      ],
                      "default": null
                    }
                  }
                },
                "image": {
                  "$omitEmpty": {
                    "$map": {
                      "from": {
                        "$filter": {
                          "from": {
                            "$sortByOrder": {
                              "$ref": "request.images"
                            }
                          },
                          "as": "media",
                          "where": {
                            "$ne": [
                              {
                                "$ref": "media.role"
                              },
                              "mask"
                            ]
                          }
                        }
                      },
                      "as": "media",
                      "in": {
                        "$coalesce": [
                          {
                            "$ref": "media.dataUrl"
                          },
                          {
                            "$ref": "media.url"
                          }
                        ]
                      }
                    }
                  }
                }
              },
              {
                "$coalesce": [
                  {
                    "$ref": "request.providerOptions.rightapi-image.body"
                  },
                  {
                    "$ref": "request.providerOptions.rightapi-image.extra_body"
                  },
                  {}
                ]
              }
            ]
          }
        },
        "poll": {
          "method": "GET",
          "path": "/v1/tasks/{{taskId}}"
        },
        "response": {
          "taskId": {
            "$coalesce": [
              {
                "$ref": "response.id"
              },
              {
                "$ref": "response.task_id"
              },
              {
                "$ref": "response.taskId"
              },
              {
                "$ref": "response.data.id"
              },
              {
                "$ref": "taskId"
              }
            ]
          },
          "status": {
            "$coalesce": [
              {
                "$ref": "response.status"
              },
              {
                "$ref": "response.state"
              },
              {
                "$ref": "response.data.status"
              },
              "pending"
            ]
          },
          "message": {
            "$coalesce": [
              {
                "$ref": "response.error.message"
              },
              {
                "$ref": "response.message"
              },
              {
                "$ref": "response.fail_reason"
              }
            ]
          },
          "images": {
            "$ref": "response.data"
          },
          "errorPaths": [
            "error.code",
            "error.type"
          ],
          "resultEphemeral": true
        }
      }
    ]
  }
}
```
